rules.code:
if not mainline:
    return True
prev = mainline[-1].rank
if prev == 13 and card.rank == 1:
    return True
return card.rank > prev

if not mainline:
    return True
s = card.suit.suit_name
if len(mainline) % 2 == 1:
    # completing a pair: must match the previous card's suit
    return s == mainline[-1].suit.suit_name
else:
    # starting a new pair: must differ from the previous pair's suit
    return s != mainline[-1].suit.suit_name
